<?php
namespace App\Controllers\Auth;use App\Support\App;
final class AuthController{public function login():never{$in=App::input();$q=App::db()->prepare('SELECT * FROM users WHERE email=? AND status="active"');$q->execute([trim($in['email']??'')]);$u=$q->fetch();if(!$u||!password_verify($in['password']??'',$u['password']))App::json(['ok'=>false,'message'=>'Email/password salah'],422);session_regenerate_id(true);$_SESSION['uid']=$u['id'];$_SESSION['user_name']=$u['name'];App::json(['ok'=>true,'redirect'=>$u['role']==='admin'?'/admin':'/dashboard']);}public function register():never{$in=App::input();if(App::setting('registration_enabled','1')!=='1')App::json(['ok'=>false,'message'=>'Pendaftaran ditutup'],403);$name=trim($in['name']??'');$email=trim($in['email']??'');$phone=preg_replace('/[^0-9+]/','',trim($in['phone']??''));$pass=$in['password']??'';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($phone)<8||strlen($pass)<8)App::json(['ok'=>false,'message'=>'Nama, email, nomor WhatsApp dan password wajib valid'],422);$lvl=App::db()->query("SELECT id FROM user_levels WHERE code='user'")->fetchColumn();try{App::db()->prepare('INSERT INTO users(name,email,phone,password,level_id) VALUES(?,?,?,?,?)')->execute([$name,$email,$phone,password_hash($pass,PASSWORD_DEFAULT),$lvl]);App::json(['ok'=>true]);}catch(\Throwable $e){App::json(['ok'=>false,'message'=>'Email sudah digunakan'],409);}}}